  if(n.equals("Path of Wild Magic")&&a.equals("wild_surge")){int d=in.optInt("d8_roll",0);if(d<1||d>8)return pending(o,"d8_roll 1..8");return o.put("effect",new JSONObject().put("wild_surge_roll",d).put("manual_table_resolution",true));}
  if(n.equals("College of Eloquence")&&a.equals("unsettling_words")){int die=in.optInt("bardic_inspiration_roll",0);if(die<1)return pending(o,"bardic_inspiration_roll");return o.put("effect",new JSONObject().put("next_save_penalty",die).put("expires","before start of bard next turn"));}
  if(n.equals("Peace Domain")&&a.equals("emboldening_bond")){JSONArray ids=in.optJSONArray("targets");if(ids==null)return pending(o,"targets[]");if(ids.length()>pb(l))return pending(o,"targets length <= proficiency bonus");return o.put("effect",new JSONObject().put("bonded_targets",ids).put("duration_minutes",10).put("range_ft",l>=17?60:30).put("die","1d4 once per turn"));}
  if(n.equals("Twilight Domain")&&a.equals("twilight_sanctuary"))return o.put("effect",new JSONObject().put("radius_ft",30).put("duration_minutes",1).put("end_turn_choice","1d6 + cleric level temp HP OR end charmed/frightened"));
  if(n.equals("Circle of Stars")&&a.equals("starry_form")){String f=in.optString("form","");if(!(f.equals("archer")||f.equals("chalice")||f.equals("dragon")))return pending(o,"form=archer|chalice|dragon");return o.put("effect",new JSONObject().put("form",f).put("duration_minutes",10).put("die",l>=10?"2d8":"1d8"));}
  if(n.equals("Circle of Wildfire")&&a.equals("summon_wildfire_spirit"))return o.put("effect",new JSONObject().put("consume_wild_shape_use",1).put("duration_hours",1).put("summon_burst","2d6 fire Dex save half in 10ft").put("command","bonus action; otherwise Dodge"));
