  if(n.equals("Rune Knight")&&a.equals("giants_might"))return o.put("effect",new JSONObject().put("duration_minutes",1).put("size",l>=18?"Huge":"Large").put("strength_checks_saves_advantage",true).put("once_per_turn_extra_damage",l>=18?"1d10":l>=10?"1d8":"1d6"));
  if(n.equals("Way of Mercy")&&a.equals("hand_of_healing")){int roll=in.optInt("martial_arts_die_roll",0);if(roll<1)return pending(o,"martial_arts_die_roll");return o.put("effect",new JSONObject().put("healing",roll+in.optInt("wisdom_modifier",0)).put("ki_cost",1).put("can_replace_flurry_attack",true));}
  if(n.equals("Oath of Glory")&&a.equals("inspiring_smite")){int roll=in.optInt("two_d8_roll",0);if(roll<2||roll>16)return pending(o,"two_d8_roll 2..16");return o.put("effect",new JSONObject().put("temp_hp_pool",roll+l).put("distribute_within_ft",30));}
  if(n.equals("Fey Wanderer")&&a.equals("dreadful_strikes"))return o.put("effect",new JSONObject().put("extra_psychic_damage",l>=11?"1d6":"1d4").put("once_per_turn_per_creature",true));
